"""Cookie files in every shape an operator exports them, read into the browser's cookie parameters,
and what the reader says about one — which never holds a value."""

from __future__ import annotations

import json

import pytest

from daedalus.browser import cookies

NOW = 1_800_000_000.0
LATER = int(NOW) + 86_400 * 30
PAST = int(NOW) - 86_400

NETSCAPE = (
    "# Netscape HTTP Cookie File\n"
    "# https://curl.se/docs/http-cookies.html\n"
    "# This file was generated by an extension! Edit at your own risk.\n"
    "\n"
    f".wolt.com\tTRUE\t/\tTRUE\t{LATER}\t__wtoken\tFAKE-VALUE-token-1\n"
    f"#HttpOnly_.wolt.com\tTRUE\t/\tTRUE\t{LATER}\t__wrtoken\tFAKE-VALUE-refresh-2\n"
    "auth.wolt.com\tFALSE\t/login\tFALSE\t0\tlang\tFAKE-VALUE-session-3\n"
    f".wolt.com\tTRUE\t/\tFALSE\t{PAST}\told\tFAKE-VALUE-expired-4\n"
    "this line is not a cookie\n"
    f".wolt.com\tTRUE\t/\tFALSE\t{LATER}\tempty\n"
)


def test_a_netscape_file_with_httponly_lines_host_only_cookies_and_bad_lines() -> None:
    parsed = cookies.parse(NETSCAPE.encode(), now=NOW)
    assert parsed.format == "netscape"
    by = {c["name"]: c for c in parsed.cookies}
    assert set(by) == {"__wtoken", "__wrtoken", "lang", "empty"}
    assert by["__wtoken"] == {"name": "__wtoken", "value": "FAKE-VALUE-token-1", "path": "/", "domain": ".wolt.com", "secure": True, "expires": float(LATER)}
    assert by["__wrtoken"]["httpOnly"] is True and by["__wrtoken"]["domain"] == ".wolt.com"
    # Host-only: an address, never a domain, which the browser would widen to every subdomain.
    assert by["lang"] == {"name": "lang", "value": "FAKE-VALUE-session-3", "path": "/login", "url": "http://auth.wolt.com/login"}
    assert by["empty"]["value"] == ""
    assert parsed.skipped == ["line 8 (old): expired", "line 9: not the seven tab-separated fields of a cookies.txt line"]
    assert cookies.summary(parsed) == "wolt.com 3, auth.wolt.com 1"


def test_a_cookie_editor_export() -> None:
    export = [
        {"domain": ".wolt.com", "expirationDate": LATER + 0.5, "hostOnly": False, "httpOnly": True, "name": "__wtoken", "path": "/", "sameSite": "no_restriction",
         "secure": True, "session": False, "storeId": "0", "value": "FAKE-VALUE-a"},
        {"domain": "wolt.com", "hostOnly": True, "httpOnly": False, "name": "consent", "path": "/", "sameSite": "lax", "secure": False, "session": True, "value": "FAKE-VALUE-b"},
        # SameSite=None without Secure is refused by the browser: kept, without the attribute.
        {"domain": ".wolt.com", "name": "loose", "value": "FAKE-VALUE-c", "sameSite": "no_restriction", "secure": False, "expirationDate": LATER},
        {"name": "nowhere", "value": "FAKE-VALUE-d"},
        "not an object",
    ]
    parsed = cookies.parse(json.dumps(export), now=NOW)
    by = {c["name"]: c for c in parsed.cookies}
    assert by["__wtoken"] == {"name": "__wtoken", "value": "FAKE-VALUE-a", "path": "/", "domain": ".wolt.com", "secure": True, "httpOnly": True, "sameSite": "None", "expires": LATER + 0.5}
    assert by["consent"] == {"name": "consent", "value": "FAKE-VALUE-b", "path": "/", "url": "http://wolt.com/", "sameSite": "Lax"}
    assert "sameSite" not in by["loose"]
    assert parsed.skipped == ["item 4 (nowhere): no domain", "item 5: not a cookie object"]


def test_an_editthiscookie_export_marks_a_session_cookie_and_its_ids() -> None:
    export = [{"domain": "shop.example", "hostOnly": True, "httpOnly": True, "name": "sid", "path": "/", "sameSite": "strict", "secure": True, "session": True,
               "storeId": "0", "value": "FAKE-VALUE-e", "id": 1}]
    (cookie,) = cookies.parse(json.dumps(export), now=NOW).cookies
    assert cookie == {"name": "sid", "value": "FAKE-VALUE-e", "path": "/", "url": "https://shop.example/", "secure": True, "httpOnly": True, "sameSite": "Strict"}


def test_playwright_storage_state() -> None:
    state = {
        "cookies": [
            {"name": "sid", "value": "FAKE-VALUE-f", "domain": ".shop.example", "path": "/", "expires": LATER, "httpOnly": True, "secure": True, "sameSite": "Lax"},
            {"name": "tmp", "value": "FAKE-VALUE-g", "domain": "shop.example", "path": "/", "expires": -1, "httpOnly": False, "secure": False, "sameSite": "None"},
        ],
        "origins": [{"origin": "https://shop.example", "localStorage": [{"name": "k", "value": "FAKE-VALUE-h"}]}],
    }
    parsed = cookies.parse(json.dumps(state), now=NOW)
    by = {c["name"]: c for c in parsed.cookies}
    assert by["sid"]["domain"] == ".shop.example" and by["sid"]["expires"] == LATER and by["sid"]["sameSite"] == "Lax"
    assert by["tmp"]["url"] == "http://shop.example/" and "expires" not in by["tmp"] and "sameSite" not in by["tmp"]
    assert parsed.notes == ["the file's localStorage (origins) is not imported, only its cookies"]


def test_a_devtools_copy_with_dates_and_ticks() -> None:
    copied = [
        {"name": "sid", "value": "FAKE-VALUE-i", "domain": ".shop.example", "path": "/", "expires": "2030-01-15T10:00:00.000Z", "size": 40, "httpOnly": "✓", "secure": "✓", "sameSite": "Lax"},
        {"name": "pref", "value": "FAKE-VALUE-j", "domain": "shop.example", "path": "/", "expires": "Session", "httpOnly": "", "secure": "", "sameSite": ""},
        {"name": "bad", "value": "FAKE-VALUE-k", "domain": "shop.example", "expires": "next tuesday"},
    ]
    parsed = cookies.parse(json.dumps(copied), now=NOW)
    by = {c["name"]: c for c in parsed.cookies}
    assert by["sid"]["httpOnly"] is True and by["sid"]["secure"] is True and by["sid"]["expires"] == pytest.approx(1894701600.0)
    assert "expires" not in by["pref"] and "httpOnly" not in by["pref"]
    assert parsed.skipped == ["item 3 (bad): expiry 'next tuesday' is not a time"]
    # The protocol's own Network.getAllCookies answer is the same shape, under cookies.
    protocol = {"cookies": [{"name": "a", "value": "FAKE-VALUE-l", "domain": ".x.example", "path": "/", "expires": LATER * 1000, "session": False}]}
    assert cookies.parse(json.dumps(protocol), now=NOW).cookies[0]["expires"] == LATER


def test_a_cookie_header_needs_its_site() -> None:
    parsed = cookies.parse("Cookie: sid=FAKE-VALUE-m; theme=dark=ish; broken; ;lang=FAKE-VALUE-n", domain="https://wolt.com/en", now=NOW)
    assert parsed.format == "header"
    assert [(c["name"], c["value"], c["domain"]) for c in parsed.cookies] == [("sid", "FAKE-VALUE-m", ".wolt.com"), ("theme", "dark=ish", ".wolt.com"), ("lang", "FAKE-VALUE-n", ".wolt.com")]
    assert parsed.skipped == ["pair 3: not a name=value pair"]
    with pytest.raises(cookies.CookieFileError, match="give domain"):
        cookies.parse("sid=FAKE-VALUE-o", now=NOW)


@pytest.mark.parametrize("data, said", [
    (b"", "empty"),
    (b"\xff\xfe\x00garbage", "not text"),
    (b"[1, 2", "not valid JSON"),
    (b'{"origins": []}', "a list of cookie objects"),
    (b"hello there\nthis is a letter\n", "not a cookies.txt"),
    (b"x" * (cookies.MAX_BYTES + 1), "at most"),
])
def test_what_is_not_a_cookie_file_says_so(data: bytes, said: str) -> None:
    with pytest.raises(cookies.CookieFileError, match=said):
        cookies.parse(data, now=NOW)


def test_nothing_the_reader_says_holds_a_value() -> None:
    """The summary, the skipped lines, the notes and every refusal name sites, names and lines; a value
    reaches the cookie parameters and nothing else."""
    for text in (NETSCAPE, json.dumps([{"name": "a", "value": "FAKE-VALUE-p", "domain": "x.example", "expires": PAST}, {"name": "b", "value": "FAKE-VALUE-q"}])):
        parsed = cookies.parse(text, now=NOW)
        said = " ".join([cookies.summary(parsed), *parsed.skipped, *parsed.notes])
        assert "FAKE-VALUE" not in said, said
    for bad in ('[{"name": "a", "value": "FAKE-VALUE-r", "domain": "x.example"', "FAKE-VALUE-s=1"):
        with pytest.raises(cookies.CookieFileError) as caught:
            cookies.parse(bad, now=NOW)
        assert "FAKE-VALUE" not in str(caught.value)


def test_sniff_knows_a_cookie_file_and_nothing_else() -> None:
    assert cookies.sniff(NETSCAPE.encode()) == ["wolt.com", "auth.wolt.com"]
    assert cookies.sniff(json.dumps([{"name": "a", "value": "1", "domain": f"s{i}.example"} for i in range(8)]).encode()) == [
        "s0.example", "s1.example", "s2.example", "s3.example", "s4.example", "3 more"]
    for not_cookies in (b"name=value; other=thing", b'[{"name": "Ann", "value": 3}]', b'{"cookies": "none"}', b"plain notes\n", b"", b"\xff\xfe"):
        assert cookies.sniff(not_cookies) is None, not_cookies
